CREATE TABLE "CommunityFollow" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "communityId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "CommunityFollow_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CommunityFollow_userId_communityId_key" ON "CommunityFollow"("userId", "communityId");
CREATE INDEX "CommunityFollow_communityId_createdAt_idx" ON "CommunityFollow"("communityId", "createdAt" DESC);
ALTER TABLE "CommunityFollow" ADD CONSTRAINT "CommunityFollow_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CommunityFollow" ADD CONSTRAINT "CommunityFollow_communityId_fkey" FOREIGN KEY ("communityId") REFERENCES "Community"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Business" ADD COLUMN "slug" TEXT, ADD COLUMN "website" TEXT, ADD COLUMN "publicAddress" TEXT, ADD COLUMN "latitudeApprox" DECIMAL(5,2), ADD COLUMN "longitudeApprox" DECIMAL(5,2), ADD COLUMN "openingHours" JSONB, ADD COLUMN "claimStatus" TEXT NOT NULL DEFAULT 'UNCLAIMED';
UPDATE "Business" SET "slug" = 'business-' || "id" WHERE "slug" IS NULL;
ALTER TABLE "Business" ALTER COLUMN "slug" SET NOT NULL;
CREATE UNIQUE INDEX "Business_slug_key" ON "Business"("slug");
CREATE TABLE "BusinessClaim" ("id" TEXT NOT NULL, "businessId" TEXT NOT NULL, "userId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'REQUESTED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "reviewedAt" TIMESTAMP(3), CONSTRAINT "BusinessClaim_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "BusinessClaim_businessId_userId_key" ON "BusinessClaim"("businessId", "userId");
CREATE INDEX "BusinessClaim_status_createdAt_idx" ON "BusinessClaim"("status", "createdAt" DESC);
ALTER TABLE "BusinessClaim" ADD CONSTRAINT "BusinessClaim_businessId_fkey" FOREIGN KEY ("businessId") REFERENCES "Business"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BusinessClaim" ADD CONSTRAINT "BusinessClaim_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "LocalEvent" ("id" TEXT NOT NULL, "communityId" TEXT NOT NULL, "organizerId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "category" TEXT NOT NULL, "venueName" TEXT, "locationLabel" TEXT, "latitudeApprox" DECIMAL(5,2), "longitudeApprox" DECIMAL(5,2), "startAt" TIMESTAMP(3) NOT NULL, "endAt" TIMESTAMP(3), "imageObjectKey" TEXT, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "LocalEvent_pkey" PRIMARY KEY ("id"));
CREATE INDEX "LocalEvent_communityId_startAt_idx" ON "LocalEvent"("communityId", "startAt"); CREATE INDEX "LocalEvent_status_startAt_idx" ON "LocalEvent"("status", "startAt");
ALTER TABLE "LocalEvent" ADD CONSTRAINT "LocalEvent_communityId_fkey" FOREIGN KEY ("communityId") REFERENCES "Community"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "LocalEvent" ADD CONSTRAINT "LocalEvent_organizerId_fkey" FOREIGN KEY ("organizerId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "EventAttendance" ("id" TEXT NOT NULL, "eventId" TEXT NOT NULL, "userId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'INTERESTED', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EventAttendance_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "EventAttendance_eventId_userId_key" ON "EventAttendance"("eventId", "userId"); CREATE INDEX "EventAttendance_eventId_status_idx" ON "EventAttendance"("eventId", "status"); ALTER TABLE "EventAttendance" ADD CONSTRAINT "EventAttendance_eventId_fkey" FOREIGN KEY ("eventId") REFERENCES "LocalEvent"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "EventAttendance" ADD CONSTRAINT "EventAttendance_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
